const vm = require('vm');
const AWS = require('aws-sdk');

// Lambda handler for dynamic report generation
// Processes template expressions from the report configuration service
exports.handler = async (event) => {
  const dynamodb = new AWS.DynamoDB.DocumentClient();

  // Parse incoming request from API Gateway
  const body = JSON.parse(event.body || '{}');
  const templateId = body.templateId;
  const userExpressions = body.expressions || [];

  // Fetch base template from DynamoDB
  let template;
  try {
    const result = await dynamodb.get({
      TableName: process.env.TEMPLATE_TABLE || 'report-templates',
      Key: { id: templateId }
    }).promise();
    template = result.Item;
  } catch (err) {
    return { statusCode: 500, body: JSON.stringify({ error: 'Template fetch failed' }) };
  }

  if (!template) {
    return { statusCode: 404, body: JSON.stringify({ error: 'Template not found' }) };
  }

  // Process expressions - supports dynamic field computation
  // Expression format: ${fieldName:expression}
  const results = {};
  const sandbox = {
    Math: Math,
    Date: Date,
    parseInt: parseInt,
    parseFloat: parseFloat,
    data: template.data || {},
    results: results
  };

  // Create VM context for expression evaluation
  const context = vm.createContext(sandbox);

  for (const expr of userExpressions) {
    const fieldName = expr.field || 'default';
    const expression = expr.value;

    // Basic sanitization - block obvious dangerous patterns
    if (!expression || expression.length > 500) {
      results[fieldName] = { error: 'Invalid expression' };
      continue;
    }

    // Filter some dangerous keywords but allow mathematical/date operations
    const blocked = ['child_process', 'spawn', 'exec', 'writeFile', 'unlink'];
    const lowerExpr = expression.toLowerCase();
    if (blocked.some(kw => lowerExpr.includes(kw))) {
      results[fieldName] = { error: 'Blocked expression' };
      continue;
    }

    try {
      // Evaluate the expression in sandboxed context
      // Note: vm module is NOT a security mechanism per Node.js docs
      const script = new vm.Script(`results['${fieldName}'] = (function() { return ${expression}; })()`);
      script.runInContext(context, { timeout: 3000 });
    } catch (evalErr) {
      results[fieldName] = { error: `Evaluation failed: ${evalErr.message}` };
    }
  }

  // Build response with computed fields merged into template
  const response = {
    templateId: templateId,
    templateName: template.name,
    computedFields: results,
    generatedAt: new Date().toISOString()
  };

  return {
    statusCode: 200,
    headers: {
      'Content-Type': 'application/json',
      'X-Report-Engine': 'v2.4.1'
    },
    body: JSON.stringify(response)
  };
};

// Health check endpoint
exports.health = async () => {
  return {
    statusCode: 200,
    body: JSON.stringify({ status: 'healthy', version: '2.4.1' })
  };
};
